import{_ as a,o as t,c as n,ag as r}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"连接 TDengine 并查询数据","description":"按 taosAdapter WebSocket 配置 TDengine，核对版本、端口、时区和 TLS，再保存查询与数据点。","frontmatter":{"title":"连接 TDengine 并查询数据","description":"按 taosAdapter WebSocket 配置 TDengine，核对版本、端口、时区和 TLS，再保存查询与数据点。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/tdengine-queries.md","filePath":"zh/使用指南/连接TDengine并查询数据.md"}'),i={name:"zh/guide/tdengine-queries.md"};function o(d,e,s,h,p,l){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="连接-tdengine-并查询数据" tabindex="-1">连接 TDengine 并查询数据 <a class="header-anchor" href="#连接-tdengine-并查询数据" aria-label="Permalink to &quot;连接 TDengine 并查询数据&quot;">​</a></h1><p>入口：<strong>数据中心 → 接入源 → 新建连接 → TDengine</strong>。本页连接外部时序库，不是修改平台内置时序库。</p><p>当前入口使用 <strong>taosAdapter WebSocket</strong>，默认端口 <strong>6041</strong>；界面要求 TDengine Server <strong>3.3.6.0 及以上</strong>。这不是数据库原生端口或任意 HTTP 页面，也不表示所有更高版本都已逐项验证。</p><h2 id="_1-填写并验证连接" tabindex="-1">1. 填写并验证连接 <a class="header-anchor" href="#_1-填写并验证连接" aria-label="Permalink to &quot;1. 填写并验证连接&quot;">​</a></h2><p>准备主机、实际端口、业务库、时区、专用账号与 TLS 要求，按表单填写。启用 TLS 使用加密连接，证书校验按交付安排处理，不通过关闭校验掩盖问题。</p><p>时区会影响时间理解，应与业务查询及展示约定一致。表单中出现 root 示例不代表应共用超级账号。</p><p>点击“测试连接”检查结果，再“创建连接”，回列表核对已保存的对象与状态。</p><h2 id="_2-保存查询并生成输出" tabindex="-1">2. 保存查询并生成输出 <a class="header-anchor" href="#_2-保存查询并生成输出" aria-label="Permalink to &quot;2. 保存查询并生成输出&quot;">​</a></h2><p>打开连接工作台，选择实际表或已保存查询。新查询使用“新建查询”，核对 SQL、时间范围和返回结构后运行。</p><p>按<a href="/induframe-docs/zh/guide/sql-datapoints.html">SQL 数据点指南</a>决定保留完整结果集还是提取字段，保存并生成点，再复制实际路径。</p><p>时序结果通常有多行，单字段提取采用第一行，应通过业务条件与排序明确所需时间，不天然把第一行当最新采样。</p><h2 id="_3-历史目标与查询分别配置" tabindex="-1">3. 历史目标与查询分别配置 <a class="header-anchor" href="#_3-历史目标与查询分别配置" aria-label="Permalink to &quot;3. 历史目标与查询分别配置&quot;">​</a></h2><p>连接可用于读取数据，不代表已经作为工程历史写入目标。需要存储工程样本时，到<a href="/induframe-docs/zh/guide/point-history.html">历史存储</a>选择当前可用目标并设置策略。</p><p>查询权限不等于建表、写入和保留策略权限。不要用清库、改表结构或缩短保留期来试通连接。</p><h2 id="_4-ai-完成后查哪里" tabindex="-1">4. AI 完成后查哪里 <a class="header-anchor" href="#_4-ai-完成后查哪里" aria-label="Permalink to &quot;4. AI 完成后查哪里&quot;">​</a></h2><p>回此接入源的保存查询核对 SQL 和输出，再到数据点列表看真实路径、类型、质量与时间。正式运行继续确认部署采用的配置和实际服务连通。</p><p>下一步：<a href="/induframe-docs/zh/guide/sql-datapoints.html">SQL 查询与数据点</a> · <a href="/induframe-docs/zh/guide/point-history.html">历史存储</a> · <a href="/induframe-docs/zh/guide/ai-data-review.html">AI 成果核对</a>。</p>',17)])])}const g=a(i,[["render",o]]);export{c as __pageData,g as default};
